    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'STICKER', qty: 100 }],
    terms: 'NET14',
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issuedInvoice = r2.value;

  const fee = lateFee(issuedInvoice, '2026-10-10');
  assert.equal(fee, 0);
});

test('lateFee is calculated 1 day overdue', () => {
  const r1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'STICKER', qty: 100 }],
    terms: 'NET14',
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issuedInvoice = r2.value;

  const fee = lateFee(issuedInvoice, '2026-10-16');
  assert.equal(typeof fee, 'number');
  assert.equal(fee > 0, true);
});

test('lateFee calculation: 0.04% per day on amount due', () => {
  const r1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'STICKER', qty: 100 }],
    terms: 'NET14',
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issuedInvoice = r2.value;

  const fee = lateFee(issuedInvoice, '2026-10-16');
  const amountDue = 6050;
  const daysOverdue = 1;
  const expectedFee = Math.round(amountDue * 0.0004 * daysOverdue);
  assert.equal(fee, expectedFee);
});

test('lateFee increases with days overdue', () => {
  const r1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'STICKER', qty: 100 }],
    terms: 'NET14',
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issuedInvoice = r2.value;

  const fee1 = lateFee(issuedInvoice, '2026-10-16');
  const fee10 = lateFee(issuedInvoice, '2026-10-25');
  assert.equal(fee10 > fee1, true);
  assert.equal(fee10 >= fee1 * 9, true);
});

test('lateFee with partial payment reduces amount due', () => {
  const r1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'STICKER', qty: 100 }],
    terms: 'NET14',
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issuedInvoice = r2.value;
  const r3 = recordPayment(issuedInvoice, { amount: 3000, date: '2026-10-02' });

  const feeWithoutPayment = lateFee(issuedInvoice, '2026-10-16');
  const feeWithPayment = lateFee(r3.value, '2026-10-16');
  assert.equal(feeWithPayment < feeWithoutPayment, true);
});

